// Shared binding and push-constant layout for the Z-Image DiT shaders.
//
// Same arrangement as the VAE decoder's (vae_common.glsl) and for the same
// reason: one weight arena, one activation arena, "which tensor" expressed
// as an offset, and one push-constant size across every pipeline so
// vk.DispatchMultiTimed can record a graph into one command buffer.
//
// fp32 throughout. Stage 3 is a correctness port with zimage/dit's CPU
// implementation as its oracle.

layout(binding = 0) readonly buffer Weights { float wbuf[]; };
layout(binding = 1) buffer Act { float act[]; };

layout(push_constant) uniform PC {
    uint inOff;     // input tensor
    uint outOff;    // output tensor
    uint wOff;      // weight tensor, or NO_W
    uint tokens;    // sequence length
    uint dim;       // full feature width
    uint heads;
    uint headDim;
    uint span;      // rmsnorm width: dim for the block norms, headDim for q/k
    uint kOff;      // attention: transposed keys
    uint vOff;      // attention: values
    uint kStride;   // attention: padded token stride of the transposed keys
    uint eps;       // float bits
    uint scale;     // float bits
    uint aux0;
    uint aux1;
    uint aux2;
} pc;

const uint NO_W = 0xffffffffu;
=== dit_transpose_k ===
#version 450
// Transpose keys from [tokens, heads*headDim] into per-head
// [heads][headDim][kStride], where kStride is the token count padded so the
// destination rows do not alias DRAM channels.
//
// This is not an optimisation, it is the difference between a working kernel
// and a 20x slower one. In the natural layout the score loop has thread j
// read key token j at a fixed component, so consecutive threads land
// heads*headDim*4 = 15360 B apart; IDEAS §5.1b's coverage law,
// min(1, C/gcd(stride, 4096)), gives 4/1024 -- under half a percent of the
// bus. The identical mistake in the VAE's mid-block attention measured 50
// GFLOP/s and transposing it was worth 20x.

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint total = pc.tokens * pc.heads * pc.headDim;
    if (idx >= total) {
        return;
    }
    uint d = idx % pc.headDim;
    uint h = (idx / pc.headDim) % pc.heads;
    uint token = idx / (pc.headDim * pc.heads);
    act[pc.outOff + (h * pc.headDim + d) * pc.kStride + token] =
        act[pc.inOff + token * pc.dim + h * pc.headDim + d];
}
