#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// Pack one fp32 [tokens, heads*headDim] activation into the per-head fp16
// layouts dit_attention_wmma.comp's cooperative-matrix loads want.
//
// Two modes, because the two operands of attention's two GEMMs want opposite
// things. RADV's coopMatLoad emits two `buffer_load_b128` for a row-major A
// fragment and a column-major B fragment, and *sixteen* scalar
// `buffer_load_d16_b16` for the other two combinations (shaders/gemm_wmma.comp
// documents the measurement): the hardware operand layout is K-contiguous for
// both operands. So
//
//   mode 0, [heads][tokensPad][headDim]: q as the A operand of q.k^T, whose
//     reduction axis is headDim -- and k as its B operand, since a B operand
//     stored [N, K] is exactly what "column major" means here. Both operands
//     of the first GEMM therefore share one layout, and it is the natural one.
//   mode 1, [heads][headDim][tokenStride]: v as the B operand of p.v, whose
//     reduction axis is the *token*, so K-contiguous means v transposed.
//
// Which is the same trick dit_transpose_k.comp plays for the scalar kernel,
// moved to the other operand. The row stride of each layout is chosen against
// IDEAS §5.1b/§2.3: a column-major fragment load issues 16 addresses one row
// stride apart inside one instruction, and the GEMM ablation measured those
// strides fastest 256 B past a multiple of the 2 KB channel-interleave
// period. headDim 128 halves is 256 B exactly; the transposed stride is
// padded to land in the same place.
//
// Scale folds into the pack: q carries 1/sqrt(headDim) * log2(e) so the
// kernel's softmax can use exp2 instead of exp, which on this ISA is one
// instruction instead of a multiply and one.

#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

layout(local_size_x = 256) in;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= pc.tokens * pc.dim) {
        return;
    }
    // dim == heads*headDim, so idx is also the source element index: the read
    // is contiguous in both modes and only the write scatters.
    uint d = idx % pc.headDim;
    uint h = (idx / pc.headDim) % pc.heads;
    uint token = idx / (pc.headDim * pc.heads);

    float v = act[pc.inOff + idx] * uintBitsToFloat(pc.scale);
    if (pc.aux0 == 0u) {
        hact[pc.outOff + (h * pc.aux1 + token) * pc.headDim + d] = float16_t(v);
    } else {
        hact[pc.outOff + (h * pc.headDim + d) * pc.kStride + token] = float16_t(v);
    }
}
