1	#version 450
2	#extension GL_KHR_shader_subgroup_arithmetic : require
3	// Flash-attention-style multi-head attention: one workgroup handles QB query
4	// rows of one head, streaming keys in tiles with an online softmax.
5	//
6	// This was IDEAS §3.3's first attempt; dit_attention_wmma.comp is the one that
7	// closed it, at 30.4x this kernel, and this one is kept as an fp32 oracle for
8	// it. The structure below is dictated by three measurements, taken in this
9	// order, and the last one is the only one that mattered:
10	//
11	//  1. One query row per workgroup (dit_attention.comp) measured 463 GFLOP/s
12	//     at 4096 tokens -- 0.8% of this part's matrix ceiling, and about four
13	//     minutes of attention per image over 34 blocks and 8 steps.
14	//  2. Giving QB queries a shared key tile in LDS was worth 1.09x. The reuse
15	//     was real but 16 KB of LDS took occupancy from six workgroups per CU to
16	//     two, and the latency hiding lost paid for it. Staging was removed.
17	//  3. The actual limit was arithmetic intensity, exactly as IDEAS §2.1 found
18	//     for the GEMM and as the VAE's conv2d found again: with one thread per
19	//     (query, key) pair the score loop does ONE multiply-add per 4-byte
20	//     global load. Giving each thread one key and *all* QB queries makes the
21	//     same load feed QB accumulators held in registers.
22	//
23	// The fourth measurement is the one that ended the line: at 2.67 FLOP/byte
24	// where ~28 is needed, the scalar-FMA path is an order of magnitude short of
25	// the matrix cores whatever the query block, and the matrix cores turned out to
26	// need a different operand *layout* rather than a different loop (see
27	// dit_pack_f16.comp). This kernel tops out at 1.28 TFLOP/s against 38.8.
28	//
29	// So: thread t owns key `base + t` and carries QB score accumulators. The
30	// softmax reductions are then across the workgroup rather than within a
31	// query's slice of it, which is what the subgroup arithmetic is for -- it
32	// keeps the shared footprint at a few hundred bytes instead of the 8 KB a
33	// tree over 256 threads would need, and LDS is the budget that decides
34	// occupancy here.
35	//
36	// Keys arrive transposed (dit_transpose_k.comp) so consecutive threads read
37	// consecutive tokens; §5.1b's coverage law makes that worth 20x rather than
38	// a rounding error. The running max is folded in before every exponential,
39	// which the VAE's 1.16e7 scores and this block's 5.99e5 feed-forward output
40	// make a requirement rather than a precaution.
41	
42	#include "dit_common.glsl"
43	
44	const uint QB = 8u;    // query rows per workgroup
45	const uint KT = 256u;  // keys per tile: one per thread
46	const uint HD = 128u;  // head dim; Z-Image is 3840/30
47	const uint WG = 256u;
48	
49	layout(local_size_x = 256) in;
50	
51	shared float shQ[QB * HD];
52	shared float shW[QB * KT];
53	shared float shCtx[QB * HD];
54	shared float shPart[QB * 16];   // per-subgroup partials, 16 is the worst case
55	shared float shM[QB];
56	shared float shL[QB];
57	shared float shCorr[QB];
58	
59	void main() {
60	    uint head = gl_WorkGroupID.y;
61	    uint q0 = gl_WorkGroupID.x * QB;
62	    uint t = gl_LocalInvocationID.x;
63	    uint n = pc.tokens;
64	    uint D = pc.headDim;
65	    float scale = uintBitsToFloat(pc.scale);
66	    if (q0 >= n || head >= pc.heads) {
67	        return;
68	    }
69	
70	    uint waves = gl_NumSubgroups;
71	    uint wave = gl_SubgroupID;
72	
73	    for (uint i = t; i < QB * D; i += WG) {
74	        uint qi = i / D, d = i % D;
75	        uint row = q0 + qi;
76	        shQ[i] = (row < n) ? act[pc.inOff + row * pc.dim + head * D + d] : 0.0;
77	        shCtx[i] = 0.0;
78	    }
79	    if (t < QB) {
80	        shM[t] = -1.0 / 0.0;
81	        shL[t] = 0.0;
82	    }
83	    barrier();
84	
85	    uint kHead = pc.kOff + head * D * pc.kStride;
86	
87	    for (uint base = 0u; base < n; base += KT) {
88	        uint cnt = min(KT, n - base);
89	        uint kk = t;
90	        bool live = kk < cnt;
91	
92	        // One key per thread, QB accumulators in registers: the loaded key
93	        // component is used QB times instead of once.
94	        float sc[QB];
95	        for (uint q = 0u; q < QB; ++q) {
96	            sc[q] = 0.0;
97	        }
98	        if (live) {
99	            for (uint d = 0u; d < D; ++d) {
100	                float kv = act[kHead + d * pc.kStride + base + kk];
101	                for (uint q = 0u; q < QB; ++q) {
102	                    sc[q] += shQ[q * D + d] * kv;
103	                }
104	            }
105	        }
106	        for (uint q = 0u; q < QB; ++q) {
107	            sc[q] = live ? sc[q] * scale : -1.0 / 0.0;
108	        }
109	
110	        // Per-query max over the whole workgroup, via subgroup reductions
111	        // plus a short pass over the per-wave partials.
112	        for (uint q = 0u; q < QB; ++q) {
113	            float m = subgroupMax(sc[q]);
114	            if (subgroupElect()) {
115	                shPart[q * 16u + wave] = m;
116	            }
117	        }
118	        barrier();
119	        if (t < QB) {
120	            float m = -1.0 / 0.0;
121	            for (uint w = 0u; w < waves; ++w) {
122	                m = max(m, shPart[t * 16u + w]);
123	            }
124	            float newMax = max(shM[t], m);
125	            shCorr[t] = (shM[t] == -1.0 / 0.0) ? 0.0 : exp(shM[t] - newMax);
126	            shM[t] = newMax;
127	        }
128	        barrier();
129	
130	        for (uint q = 0u; q < QB; ++q) {
131	            float w = exp(sc[q] - shM[q]);
132	            shW[q * KT + kk] = w;
133	            float sum = subgroupAdd(w);
134	            if (subgroupElect()) {
135	                shPart[q * 16u + wave] = sum;
136	            }
137	        }
138	        barrier();
139	        if (t < QB) {
140	            float s = 0.0;
141	            for (uint w = 0u; w < waves; ++w) {
142	                s += shPart[t * 16u + w];
143	            }
144	            shL[t] = shL[t] * shCorr[t] + s;
145	        }
146	        barrier();
147	
148	        // Rescale and accumulate. Thread t owns component d = t % D and the
149	        // QB/2 queries starting at 2*(t/D), so one V load feeds several
150	        // accumulators here too.
151	        uint d = t % D;
152	        uint qBase = (t / D) * (QB / 2u);
153	        for (uint j = 0u; j < cnt; ++j) {
154	            float vv = act[pc.vOff + (base + j) * pc.dim + head * D + d];
155	            for (uint u = 0u; u < QB / 2u; ++u) {
156	                uint q = qBase + u;
157	                float acc = (j == 0u) ? shCtx[q * D + d] * shCorr[q] : shCtx[q * D + d];
158	                shCtx[q * D + d] = acc + shW[q * KT + j] * vv;
159	            }
160	        }
161	        barrier();
162	    }
163	
164	    for (uint i = t; i < QB * D; i += WG) {
165	        uint qq = i / D, d = i % D;
166	        uint row = q0 + qq;
167	        if (row < n) {
168	            act[pc.outOff + row * pc.dim + head * D + d] = shCtx[i] / shL[qq];
169	        }
170	    }
171	}
